<?php
require_once __DIR__ . '/includes/header.php';
require_login();
if(!role_in(['admin','direccion','asesor'])){ flash('danger','No tienes permiso.'); redirect_to('index.php'); }
if($_SERVER['REQUEST_METHOD']==='POST'){
  $id=(int)($_POST['id']??0); $pass=$_POST['password']??'';
  try{
    if($id){
      $fields=[trim($_POST['nombre']),trim($_POST['usuario']),$_POST['rol'],(int)($_POST['puede_ver_finanzas']??0),(int)($_POST['puede_editar_precios']??0),(int)($_POST['puede_borrar']??0),(int)($_POST['es_disenador']??0),(int)($_POST['activo']??1),$id];
      db()->prepare("UPDATE v2_usuarios SET nombre=?,usuario=?,rol=?,puede_ver_finanzas=?,puede_editar_precios=?,puede_borrar=?,es_disenador=?,activo=? WHERE id=?")->execute($fields);
      if($pass!==''){ db()->prepare("UPDATE v2_usuarios SET password_hash=? WHERE id=?")->execute([password_hash($pass,PASSWORD_DEFAULT),$id]); }
    }else{
      db()->prepare("INSERT INTO v2_usuarios (nombre,usuario,password_hash,rol,puede_ver_finanzas,puede_editar_precios,puede_borrar,es_disenador,activo) VALUES (?,?,?,?,?,?,?,?,?)")->execute([trim($_POST['nombre']),trim($_POST['usuario']),password_hash($pass?:'123456',PASSWORD_DEFAULT),$_POST['rol'],(int)($_POST['puede_ver_finanzas']??0),(int)($_POST['puede_editar_precios']??0),(int)($_POST['puede_borrar']??0),(int)($_POST['es_disenador']??0),(int)($_POST['activo']??1)]);
    }
    flash('success','Usuario guardado.');
  }catch(Exception $e){ flash('danger','Error: '.$e->getMessage()); }
  redirect_to('usuarios.php');
}
$edit=null; if(isset($_GET['edit'])){ $stmt=db()->prepare("SELECT * FROM v2_usuarios WHERE id=?"); $stmt->execute([(int)$_GET['edit']]); $edit=$stmt->fetch(); }
$rows=db()->query("SELECT * FROM v2_usuarios ORDER BY activo DESC,nombre")->fetchAll();
function su($a,$b){return (string)$a===(string)$b?'selected':'';} function ck($v){return $v?'checked':'';}
?>
<h1 class="h3 mb-3">Usuarios</h1><div class="row g-3"><div class="col-lg-8"><div class="card"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Permisos</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h($r['nombre']) ?></td><td><?= h($r['usuario']) ?></td><td><?= h($r['rol']) ?></td><td class="small"><?= $r['puede_ver_finanzas']?'Finanzas ':'' ?><?= $r['puede_editar_precios']?'Precios ':'' ?><?= $r['puede_borrar']?'Borrar ':'' ?><?= $r['es_disenador']?'Diseñador':'' ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= url('usuarios.php?edit='.$r['id']) ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><div class="col-lg-4"><div class="card"><div class="card-header"><?= $edit?'Editar':'Nuevo' ?> usuario</div><div class="card-body"><form method="post"><input type="hidden" name="id" value="<?= h($edit['id']??'') ?>"><label class="form-label">Nombre</label><input class="form-control mb-2" name="nombre" value="<?= h($edit['nombre']??'') ?>" required><label class="form-label">Usuario</label><input class="form-control mb-2" name="usuario" value="<?= h($edit['usuario']??'') ?>" required><label class="form-label">Contraseña <?= $edit?'nueva':'' ?></label><input class="form-control mb-2" name="password" type="password" placeholder="Dejar vacío para no cambiar"><label class="form-label">Rol</label><select class="form-select mb-2" name="rol"><option value="admin" <?= su($edit['rol']??'','admin') ?>>Admin</option><option value="direccion" <?= su($edit['rol']??'','direccion') ?>>Dirección</option><option value="administracion" <?= su($edit['rol']??'','administracion') ?>>Administración</option><option value="operativo" <?= su($edit['rol']??'','operativo') ?>>Operativo</option><option value="disenador" <?= su($edit['rol']??'','disenador') ?>>Diseñador</option><option value="externo" <?= su($edit['rol']??'','externo') ?>>Externo</option><option value="asesor" <?= su($edit['rol']??'','asesor') ?>>Asesor</option></select><div class="form-check"><input class="form-check-input" type="checkbox" name="puede_ver_finanzas" value="1" <?= ck($edit['puede_ver_finanzas']??0) ?>><label class="form-check-label">Puede ver finanzas/ganancia</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="puede_editar_precios" value="1" <?= ck($edit['puede_editar_precios']??0) ?>><label class="form-check-label">Puede editar precios</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="puede_borrar" value="1" <?= ck($edit['puede_borrar']??0) ?>><label class="form-check-label">Puede borrar</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="es_disenador" value="1" <?= ck($edit['es_disenador']??0) ?>><label class="form-check-label">Es diseñador</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="activo" value="1" <?= ck($edit['activo']??1) ?>><label class="form-check-label">Activo</label></div><button class="btn btn-primary w-100 mt-3">Guardar</button></form></div></div></div></div>
<?php require_once __DIR__ . '/includes/footer.php'; ?>
